const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=Boolean(input.dnc||input.do_not_contact);
const leadId=input.lead_id, dealId=input.deal_id, propertyId=input.property_id;
const contractPrice=Number(input.contract_price??input.offer_price??input.accepted_price);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const signatureStatus=String(input.signature_status??input.status??"").toLowerCase();
const provider=String(input.signature_provider??input.provider??"").trim();
const providerEnvelopeId=String(input.provider_envelope_id??input.envelope_id??"").trim();
const identityReady=Boolean(leadId&&dealId&&propertyId);
const priceProtected=Number.isFinite(contractPrice)&&Number.isFinite(mao)&&contractPrice>0&&mao>0&&contractPrice<=mao;
let state="blocked",nextWorkflow="WF-126",human=true,reason="";
if(dnc){reason="DNC protection blocks signature execution";}
else if(blockers.length){reason="active blockers prevent signature execution";}
else if(!identityReady){reason="lead/deal/property identity is incomplete";}
else if(!priceProtected){reason="contract price is invalid or exceeds protected dynamic MAO";}
else if(!provider){reason="signature provider is missing";}
else if(!signatureStatus){state="dispatch_ready";nextWorkflow="WF-303";reason="validated contract is ready for signature dispatch";}
else if(["sent","dispatched","awaiting_signature","pending"].includes(signatureStatus)){state="awaiting_signature";nextWorkflow="WF-303";reason="signature envelope is active and awaiting execution";}
else if(["signed","executed","completed"].includes(signatureStatus)){state="executed";nextWorkflow="WF-303";reason="signature execution reported complete; transaction readiness can proceed";}
else if(["declined","rejected"].includes(signatureStatus)){state="declined";nextWorkflow="WF-204";human=true;reason="seller declined signature; route to recovery/disposition handling";}
else if(["expired","void","canceled","cancelled"].includes(signatureStatus)){state="expired";nextWorkflow="WF-204";human=true;reason="signature request expired or was voided";}
else{state="unknown_signature_state";nextWorkflow="WF-126";reason="unrecognized signature provider status requires review";}
const idempotencyKey=input.idempotency_key||`wf-302:${dealId||"unknown"}:${providerEnvelopeId||input.contract_version||input.version||1}`;
return [{json:{...input,workflow:"WF-302",workflow_name:"Signature Launch → Execution Tracking & Signature Outcome Controller",status:state,signature_execution:{state,signature_provider:provider||null,provider_envelope_id:providerEnvelopeId||null,contract_price:Number.isFinite(contractPrice)?contractPrice:null,dynamic_mao:Number.isFinite(mao)?mao:null,price_protected:priceProtected,identity_ready:identityReady},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"signature_execution_outcome",idempotency_key:idempotencyKey,reason}}}];
